package com.catpack.pet;
import android.app.*;import android.os.*;import android.provider.Settings;import android.content.*;import android.net.Uri;import android.widget.*;import android.graphics.Color;
public class MainActivity extends Activity {
 TextView status; android.content.SharedPreferences cfg;
 void button(LinearLayout l,String label,Runnable run){Button b=new Button(this);b.setText(label);l.addView(b);b.setOnClickListener(v->run.run());}
 void label(LinearLayout l,String s){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.rgb(58,42,42));v.setTextSize(17);v.setPadding(0,16,0,6);l.addView(v);}
 Spinner choices(LinearLayout l,String title,String key,String[] values){label(l,title);Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));s.setSelection(Math.max(0,Math.min(values.length-1,cfg.getInt(key,0))));l.addView(s);return s;}
 public void onCreate(Bundle saved){super.onCreate(saved);ProfileDefaults.ensure(this);cfg=getSharedPreferences("config",0);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(28,40,28,36);l.setBackgroundColor(Color.rgb(246,241,231));ScrollView scroll=new ScrollView(this);scroll.addView(l);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
 label(l,"🐾 "+getString(R.string.app_name));label(l,"Seu companheiro virtual. Toque para fazer carinho e abrir os cuidados. Arraste até a lateral para escalar.");
 status=new TextView(this);l.addView(status);button(l,"1 · Permitir sobreposição",()->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));
 label(l,"Nome");EditText name=new EditText(this);name.setSingleLine(true);name.setText(cfg.getString("name","Mingau"));name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(24)});l.addView(name);
 Spinner sex=choices(l,"Sexo","sex",new String[]{"Macho","Fêmea"});
 Spinner personality=choices(l,"Personalidade","personality",new String[]{"Equilibrado","Bravo","Carinhoso","Fofo","Preguiçoso"});
 Spinner skin=choices(l,"Personagem / fantasia do pack","skin",new PetCatalog(this).names());
 Spinner fur=choices(l,"Cor do pelo","fur",new String[]{"Original","Cinza","Caramelo","Branco","Lilás"});
 Spinner eyes=choices(l,"Cor dos olhos","eyes",new String[]{"Original","Verde","Azul","Âmbar"});
 Spinner outfit=choices(l,"Roupinha / acessório","outfit",new String[]{"Sem acessório","Coleira vermelha","Laço rosa","Chapéu de mago","Camisetinha azul"});
 Spinner theme=choices(l,"Tema do menu de cuidados","theme",new String[]{"Aconchegante","Pastel","Fantasia"});
 label(l,"Tamanho na tela");TextView sz=new TextView(this);l.addView(sz);SeekBar zoom=new SeekBar(this);zoom.setMax(104);zoom.setProgress(cfg.getInt("size",88)-56);sz.setText((zoom.getProgress()+56)+" dp · pixel art sem borrão");l.addView(zoom);zoom.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean u){sz.setText((n+56)+" dp · pixel art sem borrão");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
 button(l,"2 · Salvar e iniciar / atualizar gato",()->{cfg.edit().putString("name",name.getText().toString().trim().isEmpty()?"Mingau":name.getText().toString().trim()).putInt("sex",sex.getSelectedItemPosition()).putInt("personality",personality.getSelectedItemPosition()).putInt("skin",skin.getSelectedItemPosition()).putInt("fur",fur.getSelectedItemPosition()).putInt("eyes",eyes.getSelectedItemPosition()).putInt("outfit",outfit.getSelectedItemPosition()).putInt("theme",theme.getSelectedItemPosition()).putInt("size",zoom.getProgress()+56).apply();if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);try{startForegroundService(new Intent(this,PetService.class));Toast.makeText(this,"Seu gato está na tela!",Toast.LENGTH_SHORT).show();}catch(RuntimeException e){Toast.makeText(this,"Não foi possível iniciar. Confira a permissão de sobreposição.",Toast.LENGTH_LONG).show();}});
 button(l,"Parar gato",()->stopService(new Intent(this,PetService.class)));
 label(l,"Saciedade, energia e humor ficam salvos. O gato não morre: cuide dele no seu ritmo. O sexo é uma informação do perfil; a personalidade muda suas reações e atividade.\n\nA animação pausa com a tela apagada. Você pode precisar liberar o uso de bateria nas configurações do aparelho. O app não pede acesso à internet.");
 }
 protected void onResume(){super.onResume();status.setText(Settings.canDrawOverlays(this)?"✓ Sobreposição permitida":"Permita aparecer sobre outros apps para começar.");}
}
